#!/usr/bin/env bash
# usage: [S=<store or scratch root>] bash claims-457.sh ; prints K1..K12, read-only
set -u
L=/home/runner/czaba-project/tmp/studio-real-loop
S="${S:-/home/runner/czaba-project/store}"
cd "$S" || exit 2
echo "K1 head=$(git rev-parse --short HEAD) gate456=$(python3 -I -c "import json;print(json.load(open('$L/gates/gate-round-456.json'))['status'])") gate455commit=$(python3 -I -c "import json;print(json.load(open('$L/gates/gate-round-455.json')).get('commit','')[:7])")"
echo "K2 dirty=$(git status --short --untracked-files=all | wc -l)"
echo "K3 import_statement=$(grep -c 'const IMPORT_STATEMENT =' app/lib/__tests__/helpers/style-scan.ts) brace_class=$(grep -c "(?:type\\\\s+)?(\[\\\\w\$\*\\\\s{},\]\*?)" app/lib/__tests__/helpers/style-scan.ts)"
echo "K4 animations_barrel_comment=$(sed -n '7,20p' app/components/animations/index.ts | grep -c '//') index_imports_scrollreveal=$(grep -c "ScrollReveal.*from '~/components/animations'\|from '~/components/animations'" app/routes/_index.tsx)"
echo "K5 worker_urls=$(grep -rlE "new URL\(['\"]\.\.?/[^'\"]+worker" app | sort | tr '\n' ' ')"
echo "K6 export_star_as_in_app=$(grep -rnE 'export\s+(type\s+)?\*\s*as' app --include=*.ts --include=*.tsx | grep -v __tests__ | wc -l) side_effect_local_imports=$(grep -rnE "^\s*import\s+['\"](~/|\.\.?/)" app --include=*.ts --include=*.tsx | grep -v __tests__ | wc -l)"
echo "K7 walker_fns=$(grep -cE 'export function (mountGraphImports|unfollowedLocalSpecifiers)' app/lib/__tests__/helpers/style-scan.ts) gt5b_reader=$(grep -oE '(resolvedImports|mountGraphImports)\(source, importer\)' app/lib/__tests__/store-gradient-text.test.ts | head -1)"
echo "K8 tests_lt9=$(grep -c "it('LT9:" app/lib/__tests__/store-live-teal.test.ts) expect_live_teal=$(grep -o 'expect(' app/lib/__tests__/store-live-teal.test.ts | wc -l) expect_gradient=$(grep -o 'expect(' app/lib/__tests__/store-gradient-text.test.ts | wc -l) expect_glow=$(grep -o 'expect(' app/lib/__tests__/store-glow-shadow.test.ts | wc -l)"
echo "K9 doc299_l4=$(sed -n 4p docs/implementation/2026/quarter-IV/299-store-2b-3c-2-shared-rule-reader.md 2>/dev/null) | doc298_l4=$(sed -n 4p docs/implementation/2026/quarter-IV/298-saba-b-14-store-seek-thumb.md)"
echo "K10 protected_untouched=$(git status --short -- 'app/routes/studio.$productId.tsx' app/routes/api.studio-token.ts app/routes/account.downloads.tsx app/styles app/components app/root.tsx vitest.config.ts package.json | wc -l)"
echo "K11 delta_sha=$(cd $L/b-round-456 && sha256sum -c sketch-457-delta.sha256 2>&1 | tr '\n' ' ')"
echo "K12 mutants_lines=$(wc -l < $L/b-round-456/mutants/mutants.txt) red=$(grep -c ' RED ' $L/b-round-456/mutants/mutants.txt) green=$(grep -c 'GREEN' $L/b-round-456/mutants/mutants.txt) reached_v2=$(grep -c '^R ' $L/b-round-456/probe/sweep-fix-v2.txt) reached_old=$(grep -c '^R ' $L/b-round-456/probe/sweep-old-reached.txt) lost=$(comm -23 <(grep '^R ' $L/b-round-456/probe/sweep-old-reached.txt | sort) <(grep '^R ' $L/b-round-456/probe/sweep-fix-v2.txt | sort) | wc -l)"
echo "K13 covering=$(grep -E '^\s+Tests ' $L/b-round-456/precheck-covering.log | grep -oE '[0-9]+ passed' | head -1) full=$(sed -E 's/\x1b\[[0-9;]*m//g' $L/b-round-456/precheck-full-raw.log | grep -E '^\s+(Test Files|Tests) ' | grep -oE '[0-9]+ passed' | tr '\n' '/') full_rc=$(grep -oE '^rc [0-9]+' $L/b-round-456/precheck-full-raw.log) lint=$(grep -oE 'Found [0-9]+ warnings' $L/b-round-456/precheck-lint.log) tsc_bytes=$(wc -c < $L/b-round-456/precheck-typecheck.log) biome=$(grep -oE 'No fixes applied|Found [0-9]+ errors?' $L/b-round-456/precheck-biome-scoped.log | head -1) apply=$(tail -1 $L/b-round-456/apply-check.txt) expect_counts=$(tr '\n' ';' < $L/b-round-456/expect-counts.txt)"
M=0; for f in b-round-456/sketch-457-delta.patch.txt b-round-456/sketch-457-delta.sha256 b-round-456/sketch-files-sha256.txt b-round-456/sketch-review.md b-round-456/grants-457.txt b-round-456/covering-457.txt b-round-456/run-mutants.sh b-round-456/mutants/mutants.txt b-round-456/probe/zz-sweep-v2.test.ts b-round-456/probe/sweep-fix-v2.txt b-round-456/probe/sweep-sketch456.txt b-round-456/probe/flips-288-to-v2.txt b-round-456/expect-counts.txt b-round-456/apply-check.txt b-round-456/precheck-covering.log b-round-456/precheck-full-raw.log b-round-456/precheck-lint.log b-round-456/precheck-typecheck.log b-round-456/precheck-biome-scoped.log b-round-456/claims-457-planning-output.txt b-round-456/claims-457-head-output.txt b-round-456/claims-457-expected-after-A.txt b-round-455/sketch-456.patch.txt b-round-455/sketch-files-sha256.txt b-round-448/probe/warm.cjs b-round-453/probe/c12-run/c12-from-c448.cjs c-round-456/c12-tree.json c-round-456/flip-probe-c.log tools/l57-check.py mock-api/server.mjs tasks/round-456.md b-round-455-checkpoint-request.md; do [ -e "$L/$f" ] || { echo "K14 MISSING $f"; M=$((M+1)); }; done; echo "K14 cited_paths_missing=$M"
